"""The ``models`` of a ``plot`` scene (Phase W, DESIGN §97.8): data generated by a model — an
ODE system, a recurrence, a seeded random walk or Poisson process, or a function registered
through ``vidgen.api.register_model`` — checked with clear messages and run once per set of
inputs (cached), then read by series like the columns of a CSV."""

from typing import Any, Literal

from vidgen.api import *

#: Model kinds.
MODEL_KINDS = ("ode", "recurrence", "random_walk", "poisson", "function")
#: The keys each kind uses (besides kind); any other key given is an error.
_KEYS = {
    "ode": {"equations", "initial", "params", "t", "step", "method", "tolerance", "samples", "quantities", "conserved", "units"},
    "recurrence": {"equations", "initial", "params", "steps", "quantities", "conserved", "units"},
    "random_walk": {"steps", "seed", "step", "p", "dims", "distribution", "quantities", "units"},
    "poisson": {"rate", "t", "seed", "quantities", "units"},
    "function": {"function", "params", "seed", "quantities", "conserved", "units"},
}
_NEEDED = {"ode": ("equations", "initial"), "recurrence": ("equations", "initial"), "poisson": ("rate",), "function": ("function",)}
#: Simulations already run, by their inputs (validation and rendering resolve a plot more than once).
_CACHE: dict[str, Any] = {}


class PlotModel(SceneParams):
    """A model generating data: ``{kind: ode | recurrence | random_walk | poisson | function, ...}``."""

    kind: Literal["ode", "recurrence", "random_walk", "poisson", "function"]
    """ode (differential equations), recurrence (x[n+1] from x[n]), random_walk, poisson (random events in time), function (registered in Python)."""
    equations: dict[str, str] = Field(default_factory=dict)
    """ode: the derivative of each variable, {x: v, v: "-k*x - c*v"} (keys x, dx/dt or x'); recurrence: the next value, {x: "r*x*(1 - x)"}."""
    initial: dict[str, float] = Field(default_factory=dict)
    """Starting value of every variable: {x: 1, v: 0}."""
    params: dict[str, float] = Field(default_factory=dict)
    """Named parameters the equations (and quantities) use: {k: 4, c: 0.3}; function: passed to it."""
    t: tuple[float, float] | None = None
    """ode, poisson: the time span [start, end]; default [0, 10]."""
    step: float | None = Field(default=None, gt=0)
    """ode: the integration step (rk4, leapfrog; default a thousandth of the span; rk45: the first step); random_walk: the length of a step (default 1)."""
    method: str = "rk4"
    """ode: rk4 (fixed step, 4th order), rk45 (adaptive Dormand–Prince, tolerance), leapfrog (velocity Verlet: symplectic, keeps the energy of orbits and oscillators; needs x' = v pairs and forces without velocities)."""
    tolerance: float = Field(default=1e-6, gt=0, lt=0.1)
    """ode, rk45: the relative error allowed per step."""
    samples: int | None = Field(default=None, ge=10, le=5000)
    """ode: how many points to keep for drawing (default 600)."""
    steps: int | None = Field(default=None, ge=1, le=100000)
    """recurrence: how many iterations (default 50); random_walk: how many steps (default 100)."""
    seed: int = 1
    """random_walk, poisson, function: the random seed (the same seed gives the same numbers)."""
    p: float = Field(default=0.5, ge=0, le=1)
    """random_walk (1-D lattice): the chance of a step up."""
    dims: Literal[1, 2] = 1
    """random_walk: 1 (x) or 2 (x and y)."""
    distribution: Literal["lattice", "gaussian"] = "lattice"
    """random_walk: lattice (±step) or gaussian (normal steps)."""
    rate: float | None = Field(default=None, gt=0)
    """poisson: events per unit of time."""
    function: str | None = None
    """function: the name it was registered under (vidgen.api.register_model)."""
    quantities: dict[str, str] = Field(default_factory=dict)
    """Derived columns, expressions of the columns and params: {E: "0.5*v^2 + 0.5*k*x^2"}."""
    conserved: list[str] = Field(default_factory=list)
    """Quantities that should stay constant (an energy): their drift is checked (vidgen lint)."""
    units: dict[str, str] = Field(default_factory=dict)
    """Units of the columns: {t: s, x: m, v: m/s, E: J} (axis titles, readouts)."""

    @field_validator("method")
    @classmethod
    def _method(cls, v: str) -> str:
        m = plotcore.METHOD_ALIASES.get(v, v)
        if m not in plotcore.ODE_METHODS:
            raise ValueError(f"method '{v}' is not one of {', '.join(plotcore.ODE_METHODS)}" + did_you_mean(v, list(plotcore.ODE_METHODS)))
        return m

    @model_validator(mode="after")
    def _keys(self) -> "PlotModel":
        allowed = _KEYS[self.kind]
        extra = sorted(k for k in self.model_fields_set - {"kind"} if k not in allowed)
        if extra:
            raise ValueError(f"kind: {self.kind} does not use {', '.join(extra)} (it takes {', '.join(sorted(allowed))})")
        for key in _NEEDED.get(self.kind, ()):
            if key not in self.model_fields_set or not getattr(self, key):
                raise ValueError(f"kind: {self.kind} needs {key}" + (" (e.g. {x: v, v: \"-k*x\"})" if key == "equations" else ""))
        if self.t is not None and not self.t[1] > self.t[0]:
            raise ValueError(f"t must be [start, end] with end > start, got [{self.t[0]:g}, {self.t[1]:g}]")
        return self

    def run(self, name: str) -> Any:
        """The :class:`plotcore.Simulation` (cached); raises ``VidgenError`` naming the model."""
        key = name + "\0" + self.model_dump_json()
        if self.kind != "function" and key in _CACHE:
            return _CACHE[key]
        where = f"model '{name}'"
        span = self.t or (0.0, 10.0)
        if self.kind == "ode":
            sim = plotcore.simulate_ode(self.equations, self.initial, params=self.params, t=span, step=self.step, method=self.method,
                                        rtol=self.tolerance, samples=self.samples, quantities=self.quantities, conserved=self.conserved,
                                        units=self.units, source=where)
        elif self.kind == "recurrence":
            sim = plotcore.simulate_recurrence(self.equations, self.initial, params=self.params, steps=self.steps or 50, quantities=self.quantities,
                                               conserved=self.conserved, units=self.units, source=where)
        elif self.kind == "random_walk":
            sim = plotcore.random_walk(steps=self.steps or 100, seed=self.seed, step=self.step or 1.0, p=self.p, dims=self.dims,
                                       distribution=self.distribution, quantities=self.quantities, units=self.units, source=where)
        elif self.kind == "poisson":
            sim = plotcore.poisson_process(rate=float(self.rate or 1.0), t=span, seed=self.seed, quantities=self.quantities, units=self.units, source=where)
        else:
            sim = plotcore.run_registered(str(self.function), params=self.params, seed=self.seed, quantities=self.quantities,
                                          conserved=self.conserved, units=self.units, source=where)
        if self.kind != "function":
            if len(_CACHE) > 64:
                _CACHE.clear()
            _CACHE[key] = sim
        return sim


__all__ = ["MODEL_KINDS", "PlotModel"]
